const SvgWrapper = styled.div`
  width: min(80vw, 80vh);
  max-width: 363px;
  max-height: 376px;
`

const TracePath = styled.path`
  fill: none;
  stroke: black;
  stroke-width: 7;
  stroke-miterlimit: 10;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1.05;
  stroke-dashoffset: 1.05;
  animation: ${tracePath} 1.8s ease-in-out forwards;
`

function LoadingScreen({ onComplete }) {
  const [fading, setFading] = useState(false)
  const overlayRef = useRef(null)
  const timerRef = useRef(null)

  const handleTraceEnd = useCallback(() => {
    const fontsReady = document.fonts.ready
    const timeout = new Promise((resolve) => setTimeout(resolve, 3500))
    Promise.race([fontsReady, timeout]).then(() => {
      timerRef.current = setTimeout(() => setFading(true), 150)
    })
  }, [])

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current)
    }
  }, [])

  const handleFadeEnd = useCallback(
    (e) => {
      if (e.target === overlayRef.current && e.propertyName === 'opacity') {
        onComplete?.()
      }
    },
    [onComplete]
  )

  return (
    <Overlay
      ref={overlayRef}
      $fading={fading}
      onAnimationEnd={handleFadeEnd}
    >
      <SvgWrapper>
        <svg
          viewBox="0 0 363 376"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          style={{ width: '100%', height: 'auto', display: 'block' }}
        >
          <TracePath
            pathLength={1}
            d={PATH_DATA}
            onAnimationEnd={handleTraceEnd}
          />
        </svg>
      </SvgWrapper>
    </Overlay>
  )
}

export default LoadingScreen
